A.cards("c7s5",[{"id": "g7-5-standard", "h": "7.5 · Mechanisms and evidence", "c": ["c7-5-core"], "src": ["TB7:7.5"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Classify gravel and sand</h4><ul class=\"e2-note-points\"><li>Lithification turns loose sediment into rock. Rounded gravel produces conglomerate; angular gravel produces breccia.</li><li>Sand-sized grains make sandstone. These names describe the preserved clasts, rather than a unique depositional setting. Grain composition and roundness refine the description after the main size-based classification.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Distinguish sandstone varieties</h4><ul class=\"e2-note-points\"><li>Arkose contains at least twenty-five percent sand-sized feldspar in this course source. Preserved feldspar commonly supports rapid burial after derivation from crystalline rocks.</li><li>Quartz sandstone contains mostly quartz, reflecting a quartz-rich source or destruction of weaker grains. Graywacke contains a mixture of mineral and rock-fragment compositions.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Recognize the finest rocks</h4><ul class=\"e2-note-points\"><li>Siltstone contains silt-sized particles, commonly quartz. Shale contains very fine, aligned clay-rich material and splits into thin sheets or chips.</li><li>That splitting behavior matters when distinguishing shale from other mudrocks. Use the source photographs with the texture descriptions, rather than choosing a rock from color alone.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Compact grains and expel water</h4><ul class=\"e2-note-points\"><li>Burial adds weight. During compaction, grains move closer together, pore space shrinks, and water or air is expelled.</li><li>Platy clay particles can rotate toward parallel orientations as a layer thins. The grains remain solid: compaction is packing, not melting, and some pore space can remain even after burial.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Cement the remaining pores</h4><ul class=\"e2-note-points\"><li>Water moving through connected pores carries dissolved components. New minerals precipitate around grains and bind them as cement.</li><li>Four common cements here are calcite, silica, clay minerals and iron oxides. Silica can make a resistant rock, calcite can redissolve, and iron oxides commonly redden it. Cementation and compaction are different contributions to lithification.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Key distinctions</h4><ul class=\"e2-note-points\"><li>Rounded gravel-sized clasts → <mark class=\"e2-study-term\">Conglomerate</mark>.</li><li>Angular gravel-sized clasts → <mark class=\"e2-study-term\">Breccia</mark>.</li><li>Sand with at least 25% feldspar → <mark class=\"e2-study-term\">Arkose</mark>.</li><li>Mostly quartz sand grains → <mark class=\"e2-study-term\">Quartz sandstone</mark>.</li><li>Quartz, feldspar, mica and rock-fragment mixture → <mark class=\"e2-study-term\">Graywacke</mark>.</li><li>Compaction of platy clay-rich sediment with thin splitting → <mark class=\"e2-study-term\">Shale</mark>.</li></ul></section><details><summary>Original figures for this section</summary><figure><a href=\"assets/figures/chapter7-standard/7.5-p7-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.5-p7-Im1.png\" alt=\"Original course illustration for section 7.5, PDF page 7\"></a><figcaption>Exploring Geology · 7.5 · PDF p7 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.5-p8-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.5-p8-Im1.png\" alt=\"Original course illustration for section 7.5, PDF page 8\"></a><figcaption>Exploring Geology · 7.5 · PDF p8 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.5-p9-Im2.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.5-p9-Im2.png\" alt=\"Original course illustration for section 7.5, PDF page 9\"></a><figcaption>Exploring Geology · 7.5 · PDF p9 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.5-p4-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.5-p4-Im1.png\" alt=\"Original course illustration for section 7.5, PDF page 4\"></a><figcaption>Exploring Geology · 7.5 · PDF p4 · original figure; geometry retained</figcaption></figure></details>", "examId": "exam2", "traps": ["Use the specific observations and source figure. A rock name or color alone rarely establishes one unique environment."], "media": []}]);
