L.EXAM2.topics.push({"id": "E2C7S6", "ch": 7, "title": "7.6 · Build sedimentary rocks without transported clasts", "sections": ["7.6"], "concepts": ["c7-6-core"], "sources": ["TB7:7.6"], "media": [{"kind": "img", "src": "assets/figures/chapter7-standard/7.6-p2-Im1.png", "width": 700, "height": 474, "alt": "Original course illustration for section 7.6, PDF page 2", "cap": "Exploring Geology · 7.6 · PDF p2 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.6-p3-Im1.png", "width": 1500, "height": 1012, "alt": "Original course illustration for section 7.6, PDF page 3", "cap": "Exploring Geology · 7.6 · PDF p3 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.6-p6-Im1.png", "width": 762, "height": 420, "alt": "Original course illustration for section 7.6, PDF page 6", "cap": "Exploring Geology · 7.6 · PDF p6 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.6-p7-Im1.png", "width": 740, "height": 509, "alt": "Original course illustration for section 7.6, PDF page 7", "cap": "Exploring Geology · 7.6 · PDF p7 · original figure; geometry retained"}], "standardChapter7": true});
