L.CH7_STANDARD.lessons.push({"n": 8, "bank": [["Angular shattered rock in a chaotic deposit", "Landslide breccia"], ["Muddy slurry carries large fragments down a canyon", "Debris-flow deposit"], ["Fan-shaped deposit at a mountain front", "Alluvial fan"], ["Rounded gravel in migrating channels", "Stream conglomerate"], ["Repeated waves round stones in place", "Beach reworking"]]});
A.cards("c7s8",[{"id": "g7-8-standard", "h": "7.8 · Mechanisms and evidence", "c": ["c7-8-core"], "src": ["TB7:7.8"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Read the angular jumble</h4><ul class=\"e2-note-points\"><li>Breccia contains angular large clasts in a finer matrix and is commonly poorly sorted. Massive lenses or wedges may have little visible bedding because material arrived in a sudden chaotic event.</li><li>Some fragments remain shattered but close together. These observations support limited rounding, but do not identify one unique environment.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Deposit breccia in several ways</h4><ul class=\"e2-note-points\"><li>Mudflows and debris flows carry mixtures down steep slopes. Landslides shatter rock during movement.</li><li>Streams can build coarse alluvial fans at a mountain front, and glaciers can leave mixtures of large fragments and fine rock flour.</li><li>Breccia is compatible with several of these settings, so inspect matrix, geometry and surrounding deposits.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Round gravel into conglomerate</h4><ul class=\"e2-note-points\"><li>Conglomerate has rounded gravel-sized clasts in sand or mud. Some beds have many touching clasts and little matrix; others contain scattered gravel within finer material.</li><li>Rounding usually records abrasion and reworking. Smaller gravel can reflect weaker flow, a finer source, long abrasion or a combination of those factors.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Transport gravel in rivers and waves</h4><ul class=\"e2-note-points\"><li>Energetic streams and braided channels can deposit coarse gravel. Repeated wave pounding can round beach stones without moving them a great distance away.</li><li>Rounded clasts therefore do not supply one exact travel distance. Match the rock with channel forms, shoreline evidence and other observations before choosing its environment.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Carry coarse material offshore</h4><ul class=\"e2-note-points\"><li>Conglomerate can also occur in deltas and underwater flows near continental slopes. Large clasts show that an effective transporting or moving process was available; the setting need not have been dry land.</li><li>Breccia and conglomerate share coarse grain size, while angular versus rounded clasts distinguish their names.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Key distinctions</h4><ul class=\"e2-note-points\"><li>Angular shattered rock in a chaotic deposit → <mark class=\"e2-study-term\">Landslide breccia</mark>.</li><li>Muddy slurry carries large fragments down a canyon → <mark class=\"e2-study-term\">Debris-flow deposit</mark>.</li><li>Fan-shaped deposit at a mountain front → <mark class=\"e2-study-term\">Alluvial fan</mark>.</li><li>Rounded gravel in migrating channels → <mark class=\"e2-study-term\">Stream conglomerate</mark>.</li><li>Repeated waves round stones in place → <mark class=\"e2-study-term\">Beach reworking</mark>.</li></ul></section><details><summary>Original figures for this section</summary><figure><a href=\"assets/figures/chapter7-standard/7.8-p5-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.8-p5-Im1.png\" alt=\"Original course illustration for section 7.8, PDF page 5\"></a><figcaption>Exploring Geology · 7.8 · PDF p5 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.8-p5-Im2.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.8-p5-Im2.png\" alt=\"Original course illustration for section 7.8, PDF page 5\"></a><figcaption>Exploring Geology · 7.8 · PDF p5 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.8-p8-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.8-p8-Im1.png\" alt=\"Original course illustration for section 7.8, PDF page 8\"></a><figcaption>Exploring Geology · 7.8 · PDF p8 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.8-p10-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.8-p10-Im1.png\" alt=\"Original course illustration for section 7.8, PDF page 10\"></a><figcaption>Exploring Geology · 7.8 · PDF p10 · original figure; geometry retained</figcaption></figure></details>", "examId": "exam2", "traps": ["Use the specific observations and source figure. A rock name or color alone rarely establishes one unique environment."], "media": []}]);
