L.EXAM2.topics.push({"id": "E2C7S9", "ch": 7, "title": "7.9 · Explain the many origins of sandstone", "sections": ["7.9"], "concepts": ["c7-9-core"], "sources": ["TB7:7.9"], "media": [{"kind": "img", "src": "assets/figures/chapter7-standard/7.9-p4-Im1.png", "width": 670, "height": 440, "alt": "Original course illustration for section 7.9, PDF page 4", "cap": "Exploring Geology · 7.9 · PDF p4 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.9-p6-Im1.png", "width": 1500, "height": 1125, "alt": "Original course illustration for section 7.9, PDF page 6", "cap": "Exploring Geology · 7.9 · PDF p6 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.9-p8-Im1.png", "width": 767, "height": 500, "alt": "Original course illustration for section 7.9, PDF page 8", "cap": "Exploring Geology · 7.9 · PDF p8 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.9-p8-Im2.png", "width": 1500, "height": 1105, "alt": "Original course illustration for section 7.9, PDF page 8", "cap": "Exploring Geology · 7.9 · PDF p8 · original figure; geometry retained"}], "standardChapter7": true});
L.CH7_STANDARD.lessons.push({"n": 9, "bank": [["Well-sorted sand with large cross-bed sets", "Dune deposit"], ["Discrete sand layers among floodplain fines", "Stream deposit"], ["Sand, local shells and wave-reworked gravel", "Beach deposit"], ["Sand advances over earlier marine mud", "Delta progradation"], ["Graded sand beds among deep-water mud", "Turbidity-current deposits"]]});
A.cards("c7s9",[{"id": "g7-9-standard", "h": "7.9 · Mechanisms and evidence", "c": ["c7-9-core"], "src": ["TB7:7.9"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Recognize sand-dominated rock</h4><ul class=\"e2-note-points\"><li>Sandstone is dominated by sand-sized grains, commonly quartz but sometimes feldspar, volcanic fragments or other minerals. It may contain some silt or gravel while remaining sandstone.</li><li>Grains can be angular or rounded. Parallel layers, cross beds and massive-looking intervals record different patterns of deposition and preservation.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Compare desert dunes and streams</h4><ul class=\"e2-note-points\"><li>Desert dunes commonly produce well-sorted sand and large cross beds. Iron-oxide cement can give terrestrial sandstone a red color.</li><li>Streams deposit sand in channels and during floods, commonly interlayered with finer floodplain sediment. Use structures and associated deposits together; neither red color nor sandstone alone proves desert dunes.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Deposit sand on a coast</h4><ul class=\"e2-note-points\"><li>Beaches obtain sand from local rocks, reefs, rivers, wind and coastal currents. Shells or gravel may accompany it, although energetic waves can destroy fragile shells.</li><li>Wind moves some beach sand into coastal dunes. Deltas also deliver sand through channels and shallow water, so several neighboring coastal settings can produce sandstone.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Build a delta over marine mud</h4><ul class=\"e2-note-points\"><li>The source outcrop changes upward from marine shale with thin sand beds to thicker sandstone with less shale. A delta advanced over the earlier marine mud.</li><li>This records a shift toward sandier, more landward conditions at that location. Read the whole vertical sequence rather than interpreting the upper sandstone in isolation.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Carry sand beyond the shoreline</h4><ul class=\"e2-note-points\"><li>Sand can remain on a continental shelf or move into deeper water. A turbidity current carries a slurry downslope and can leave a graded sand bed among quieter marine mud deposits.</li><li>Sand near volcanoes may be rich in dark volcanic grains. Deep-water sandstone is therefore compatible with continental sediment delivered by a sudden current.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Key distinctions</h4><ul class=\"e2-note-points\"><li>Well-sorted sand with large cross-bed sets → <mark class=\"e2-study-term\">Dune deposit</mark>.</li><li>Discrete sand layers among floodplain fines → <mark class=\"e2-study-term\">Stream deposit</mark>.</li><li>Sand, local shells and wave-reworked gravel → <mark class=\"e2-study-term\">Beach deposit</mark>.</li><li>Sand advances over earlier marine mud → <mark class=\"e2-study-term\">Delta progradation</mark>.</li><li>Graded sand beds among deep-water mud → <mark class=\"e2-study-term\">Turbidity-current deposits</mark>.</li></ul></section><details><summary>Original figures for this section</summary><figure><a href=\"assets/figures/chapter7-standard/7.9-p4-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.9-p4-Im1.png\" alt=\"Original course illustration for section 7.9, PDF page 4\"></a><figcaption>Exploring Geology · 7.9 · PDF p4 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.9-p6-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.9-p6-Im1.png\" alt=\"Original course illustration for section 7.9, PDF page 6\"></a><figcaption>Exploring Geology · 7.9 · PDF p6 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.9-p8-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.9-p8-Im1.png\" alt=\"Original course illustration for section 7.9, PDF page 8\"></a><figcaption>Exploring Geology · 7.9 · PDF p8 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.9-p8-Im2.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.9-p8-Im2.png\" alt=\"Original course illustration for section 7.9, PDF page 8\"></a><figcaption>Exploring Geology · 7.9 · PDF p8 · original figure; geometry retained</figcaption></figure></details>", "examId": "exam2", "traps": ["Use the specific observations and source figure. A rock name or color alone rarely establishes one unique environment."], "media": []}]);
