A.teach("e2-c7-standard-9-write","c7-9-core","Give two source-supported sandstone settings, one on land and one offshore, and one diagnostic companion feature for each.","Wind-built dunes on land commonly leave well-sorted sand and large cross beds. Offshore turbidity currents can leave normally graded sandstone interbedded with fine marine mud. Sandstone alone does not distinguish them.",["Names a supported land setting.", "Gives its matching structure or sediment clue.", "Names a supported offshore setting.", "Gives its matching companion evidence."],["TB7:7.9"],{"examId": "exam2", "mock": false, "topics": ["E2C7S9"], "focusedWriting": true});
