L.EXAM2.topics.push({"id": "E2C7S10", "ch": 7, "title": "7.10 · Follow fine sediment into quiet settings", "sections": ["7.10"], "concepts": ["c7-10-core"], "sources": ["TB7:7.10"], "media": [{"kind": "img", "src": "assets/figures/chapter7-standard/7.10-p2-Im1.png", "width": 726, "height": 416, "alt": "Original course illustration for section 7.10, PDF page 2", "cap": "Exploring Geology · 7.10 · PDF p2 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.10-p2-Im2.png", "width": 725, "height": 457, "alt": "Original course illustration for section 7.10, PDF page 2", "cap": "Exploring Geology · 7.10 · PDF p2 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.10-p4-Im1.png", "width": 736, "height": 464, "alt": "Original course illustration for section 7.10, PDF page 4", "cap": "Exploring Geology · 7.10 · PDF p4 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.10-p9-Im2.png", "width": 1500, "height": 1000, "alt": "Original course illustration for section 7.10, PDF page 9", "cap": "Exploring Geology · 7.10 · PDF p9 · original figure; geometry retained"}], "standardChapter7": true});
L.CH7_STANDARD.lessons.push({"n": 10, "bank": [["Rock dominated by silt-sized particles", "Siltstone"], ["Fine-grained rock splits into thin chips", "Shale"], ["General rock formed from silt and clay", "Mudstone or mudrock"], ["Powdery silt deposited across land by wind", "Windblown silt"], ["Intricately drained soft sedimentary terrain", "Badlands"]]});
A.cards("c7s10",[{"id": "g7-10-standard", "h": "7.10 · Mechanisms and evidence", "c": ["c7-10-core"], "src": ["TB7:7.10"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Classify the fine-grained rocks</h4><ul class=\"e2-note-points\"><li>Siltstone is dominated by silt. Mud includes both silt and clay, and its rock can be called mudstone or mudrock.</li><li>Shale characteristically splits into thin chips or flakes. Fine grain size and splitting are separate observations. Interbedded sand or limestone and varying colors add information about a particular sequence.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Deposit fines on land</h4><ul class=\"e2-note-points\"><li>Floodwaters spread fine sediment beyond a river channel, and slow water lets silt settle. Lakes receive mud from streams, wind and nearby slopes.</li><li>Wind can also deposit extensive silt layers, especially from sediment ground by glaciers. Chemical weathering supplies clay-rich soils that may later become fine-grained rock.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Trap mud along the coast</h4><ul class=\"e2-note-points\"><li>Tidal mud flats are repeatedly flooded and exposed, sometimes leaving evaporite minerals after drying. Lagoons trap clay and mud delivered from land.</li><li>Shallow continental seas and shelves also accumulate fines. Small grain size therefore supports quiet deposition, but does not by itself mean the water was very deep.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Let deep-water mud accumulate</h4><ul class=\"e2-note-points\"><li>Fine particles carried by currents and wind can reach ocean basins. Organic-rich mud in relatively low-oxygen conditions can produce dark shale.</li><li>The interpretation depends on composition and fossils as well as color. A dark fine-grained rock is evidence to investigate, not a direct measurement of an exact ancient water depth.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Erode slopes and badlands</h4><ul class=\"e2-note-points\"><li>Shale, mudstone and siltstone commonly weather into soft slopes and loose chips. Debris from stronger cliffs can cover these weak units.</li><li>Streams preferentially erode some weak layers, while intricately drained badlands develop in easily eroded sediment. Modern slope shape helps identify resistance; depositional environment still requires the rock evidence.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Key distinctions</h4><ul class=\"e2-note-points\"><li>Rock dominated by silt-sized particles → <mark class=\"e2-study-term\">Siltstone</mark>.</li><li>Fine-grained rock splits into thin chips → <mark class=\"e2-study-term\">Shale</mark>.</li><li>General rock formed from silt and clay → <mark class=\"e2-study-term\">Mudstone or mudrock</mark>.</li><li>Powdery silt deposited across land by wind → <mark class=\"e2-study-term\">Windblown silt</mark>.</li><li>Intricately drained soft sedimentary terrain → <mark class=\"e2-study-term\">Badlands</mark>.</li></ul></section><details><summary>Original figures for this section</summary><figure><a href=\"assets/figures/chapter7-standard/7.10-p2-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.10-p2-Im1.png\" alt=\"Original course illustration for section 7.10, PDF page 2\"></a><figcaption>Exploring Geology · 7.10 · PDF p2 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.10-p2-Im2.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.10-p2-Im2.png\" alt=\"Original course illustration for section 7.10, PDF page 2\"></a><figcaption>Exploring Geology · 7.10 · PDF p2 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.10-p4-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.10-p4-Im1.png\" alt=\"Original course illustration for section 7.10, PDF page 4\"></a><figcaption>Exploring Geology · 7.10 · PDF p4 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.10-p9-Im2.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.10-p9-Im2.png\" alt=\"Original course illustration for section 7.10, PDF page 9\"></a><figcaption>Exploring Geology · 7.10 · PDF p9 · original figure; geometry retained</figcaption></figure></details>", "examId": "exam2", "traps": ["Use the specific observations and source figure. A rock name or color alone rarely establishes one unique environment."], "media": []}]);
