L.EXAM2.topics.push({"id": "E2C7S11", "ch": 7, "title": "7.11 · Make and modify carbonate rocks", "sections": ["7.11"], "concepts": ["c7-11-core"], "sources": ["TB7:7.11"], "media": [{"kind": "img", "src": "assets/figures/chapter7-standard/7.11-p4-Im1.png", "width": 664, "height": 451, "alt": "Original course illustration for section 7.11, PDF page 4", "cap": "Exploring Geology · 7.11 · PDF p4 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.11-p6-Im1.png", "width": 672, "height": 455, "alt": "Original course illustration for section 7.11, PDF page 6", "cap": "Exploring Geology · 7.11 · PDF p6 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.11-p7-Im1.png", "width": 670, "height": 427, "alt": "Original course illustration for section 7.11, PDF page 7", "cap": "Exploring Geology · 7.11 · PDF p7 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.11-p9-Im2.png", "width": 1500, "height": 1125, "alt": "Original course illustration for section 7.11, PDF page 9", "cap": "Exploring Geology · 7.11 · PDF p9 · original figure; geometry retained"}], "standardChapter7": true});
L.CH7_STANDARD.lessons.push({"n": 11, "bank": [["Rock made mainly of calcite", "Limestone"], ["Rock made mainly of dolomite", "Dolostone"], ["Waves break carbonate shells into sand", "Clastic carbonate sediment"], ["Groundwater removes soluble carbonate", "Cave development"], ["A cave roof fails and lowers the surface", "Sinkhole formation"]]});
A.cards("c7s11",[{"id": "g7-11-standard", "h": "7.11 · Mechanisms and evidence", "c": ["c7-11-core"], "src": ["TB7:7.11"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Identify limestone and dolostone</h4><ul class=\"e2-note-points\"><li>Limestone consists mainly of calcite and commonly contains fossils. It can dissolve and reacts with hydrochloric acid.</li><li>Dolostone consists mainly of dolomite and generally resists dissolution better. Carbonate can be mixed with clay or quartz, so color alone does not distinguish the minerals or establish where the rock formed.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Precipitate carbonate outside the sea</h4><ul class=\"e2-note-points\"><li>Limestone can form in evaporative lakes and as chemical deposits around springs. Porous layered travertine can accumulate in hot or cold springs, lakes and caves.</li><li>Each new layer coats material already present. The lake pillars and spring deposits are carbonate examples without requiring a marine reef at the site.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Build marine carbonate and carbonate sand</h4><ul class=\"e2-note-points\"><li>Reef organisms extract calcium carbonate to construct shells and skeletons. Their remains and lime mud accumulate on shelves.</li><li>Waves can break reef material into calcite sand that later becomes clastic limestone. Carbonate composition and clastic texture can therefore occur together. In the deepest sea, carbonate may dissolve instead of being preserved.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Replace calcite with dolomite</h4><ul class=\"e2-note-points\"><li>Magnesium-bearing fluids can interact with limestone and replace calcite with dolomite. Replacement may remain incomplete, leaving limestone and dolostone together.</li><li>This is a chemical modification of the rock, distinct from moving sand grains or simply growing a new reef. Keep original sediment formation and later mineral replacement separate.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Dissolve openings and shape the landscape</h4><ul class=\"e2-note-points\"><li>In dry settings, carbonate rocks can form resistant cliffs. In wetter conditions, dissolution exploits fractures and bedding, leaving openings, pillars and caves.</li><li>Groundwater carries dissolved carbonate away. If a cave roof collapses, a sinkhole can form. Erosion resistance depends on climate and structure, so limestone does not always produce the same landform.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Key distinctions</h4><ul class=\"e2-note-points\"><li>Rock made mainly of calcite → <mark class=\"e2-study-term\">Limestone</mark>.</li><li>Rock made mainly of dolomite → <mark class=\"e2-study-term\">Dolostone</mark>.</li><li>Waves break carbonate shells into sand → <mark class=\"e2-study-term\">Clastic carbonate sediment</mark>.</li><li>Groundwater removes soluble carbonate → <mark class=\"e2-study-term\">Cave development</mark>.</li><li>A cave roof fails and lowers the surface → <mark class=\"e2-study-term\">Sinkhole formation</mark>.</li></ul></section><details><summary>Original figures for this section</summary><figure><a href=\"assets/figures/chapter7-standard/7.11-p4-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.11-p4-Im1.png\" alt=\"Original course illustration for section 7.11, PDF page 4\"></a><figcaption>Exploring Geology · 7.11 · PDF p4 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.11-p6-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.11-p6-Im1.png\" alt=\"Original course illustration for section 7.11, PDF page 6\"></a><figcaption>Exploring Geology · 7.11 · PDF p6 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.11-p7-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.11-p7-Im1.png\" alt=\"Original course illustration for section 7.11, PDF page 7\"></a><figcaption>Exploring Geology · 7.11 · PDF p7 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.11-p9-Im2.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.11-p9-Im2.png\" alt=\"Original course illustration for section 7.11, PDF page 9\"></a><figcaption>Exploring Geology · 7.11 · PDF p9 · original figure; geometry retained</figcaption></figure></details>", "examId": "exam2", "traps": ["Use the specific observations and source figure. A rock name or color alone rarely establishes one unique environment."], "media": []}]);
