L.EXAM2.topics.push({"id": "E2C7S14", "ch": 7, "title": "7.14 · Connect sedimentary rocks with resources and history", "sections": ["7.14"], "concepts": ["c7-14-core"], "sources": ["TB7:7.14"], "media": [{"kind": "img", "src": "assets/figures/chapter7-standard/7.14-p2-Im1.png", "width": 816, "height": 678, "alt": "Original course illustration for section 7.14, PDF page 2", "cap": "Exploring Geology · 7.14 · PDF p2 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.14-p3-Im1.png", "width": 807, "height": 658, "alt": "Original course illustration for section 7.14, PDF page 3", "cap": "Exploring Geology · 7.14 · PDF p3 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.14-p4-Im1.png", "width": 818, "height": 669, "alt": "Original course illustration for section 7.14, PDF page 4", "cap": "Exploring Geology · 7.14 · PDF p4 · original figure; geometry retained"}, {"kind": "img", "src": "assets/figures/chapter7-standard/7.14-p7-Im1.png", "width": 821, "height": 683, "alt": "Original course illustration for section 7.14, PDF page 7", "cap": "Exploring Geology · 7.14 · PDF p7 · original figure; geometry retained"}], "standardChapter7": true});
L.CH7_STANDARD.lessons.push({"n": 14, "bank": [["Pores and fractures store water", "Groundwater"], ["Organic-rich rock generates oil and gas", "Petroleum source rock"], ["Granular material is screened for construction", "Aggregate"], ["Suitable limestone is processed for concrete binder", "Manufactured cement"], ["Groundwater transports and concentrates a metal", "Sedimentary uranium deposit"]]});
A.cards("c7s14",[{"id": "g7-14-standard", "h": "7.14 · Mechanisms and evidence", "c": ["c7-14-core"], "src": ["TB7:7.14"], "html": "<section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Store groundwater between grains</h4><ul class=\"e2-note-points\"><li>Much groundwater occupies pores between sediment grains and fractures in rock. Connected openings allow water to move; an isolated opening can store water without transmitting it well.</li><li>A sedimentary rock can therefore act as both a record of deposition and a host for a later fluid history.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Form, move and trap petroleum</h4><ul class=\"e2-note-points\"><li>Oil and natural gas form in organic-rich sedimentary rocks and can migrate upward. Some escape, while some collect where rock geometry and a seal trap them.</li><li>Distinguish the source that generates petroleum from the reservoir that stores it and the trapping conditions that keep it underground. A porous bed alone does not prove an oil field.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Obtain solid sedimentary resources</h4><ul class=\"e2-note-points\"><li>Coal comes from buried plant material. Suitable limestone supplies material for manufactured cement.</li><li>Salt can be mined from old deposits or harvested by evaporating brine. Migrating groundwater can concentrate uranium in sedimentary rocks. These resources have different origins even when all occur within a sedimentary sequence.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Read climate, life and past events</h4><ul class=\"e2-note-points\"><li>Modern sedimentary processes help interpret ancient deposits. Layers preserve changing environments, fossils, past climate and evidence of events such as landslides, storms and earthquakes.</li><li>Reconstruct the event from its deposit and context. The record supports understanding of past change; it does not specify the exact date of a future hazard.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Sort aggregate for construction</h4><ul class=\"e2-note-points\"><li>Sand and gravel are widely used construction resources. Material is excavated, screened into sizes and sometimes crushed.</li><li>Selected sizes can become concrete aggregate, tile ingredients or fill beneath roads and buildings. Aggregate is the granular material; manufactured cement binds a concrete mixture. Natural cement between rock grains is another use of the same word.</li></ul></section><section class=\"e2-note-group\"><h4 class=\"e2-note-heading\">Key distinctions</h4><ul class=\"e2-note-points\"><li>Pores and fractures store water → <mark class=\"e2-study-term\">Groundwater</mark>.</li><li>Organic-rich rock generates oil and gas → <mark class=\"e2-study-term\">Petroleum source rock</mark>.</li><li>Granular material is screened for construction → <mark class=\"e2-study-term\">Aggregate</mark>.</li><li>Suitable limestone is processed for concrete binder → <mark class=\"e2-study-term\">Manufactured cement</mark>.</li><li>Groundwater transports and concentrates a metal → <mark class=\"e2-study-term\">Sedimentary uranium deposit</mark>.</li></ul></section><details><summary>Original figures for this section</summary><figure><a href=\"assets/figures/chapter7-standard/7.14-p2-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.14-p2-Im1.png\" alt=\"Original course illustration for section 7.14, PDF page 2\"></a><figcaption>Exploring Geology · 7.14 · PDF p2 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.14-p3-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.14-p3-Im1.png\" alt=\"Original course illustration for section 7.14, PDF page 3\"></a><figcaption>Exploring Geology · 7.14 · PDF p3 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.14-p4-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.14-p4-Im1.png\" alt=\"Original course illustration for section 7.14, PDF page 4\"></a><figcaption>Exploring Geology · 7.14 · PDF p4 · original figure; geometry retained</figcaption></figure><figure><a href=\"assets/figures/chapter7-standard/7.14-p7-Im1.png\" target=\"_blank\" rel=\"noopener\"><img loading=\"lazy\" style=\"max-width:100%;height:auto\" src=\"assets/figures/chapter7-standard/7.14-p7-Im1.png\" alt=\"Original course illustration for section 7.14, PDF page 7\"></a><figcaption>Exploring Geology · 7.14 · PDF p7 · original figure; geometry retained</figcaption></figure></details>", "examId": "exam2", "traps": ["Use the specific observations and source figure. A rock name or color alone rarely establishes one unique environment."], "media": []}]);
